    s__LAWN_MOW(py_str("Mow little and often in the growing season, not shorter than about 4cm, and leave the clippings off unless it is long."));
    s__LAWN_DEAD(py_str("A brown lawn is usually dormant rather than dead, so check before you dig it up: pull a tuft - if the roots hold and there is green at the base it will come back after a week of deep watering, and if the tuft lifts like a mat it has gone. Dead patches want the old grass raked out and reseeded in early autumn, when the ground is warm and the rain does the watering."));
    s__LAWN_COLOUR(py_str("Yellow or brown patches in dry weather are usually thirst - water deeply once a week in a dry spell rather than a sprinkle daily - and thin pale grass in spring wants a feed rather than a reseed."));
    s__LAWN_REST(py_str("Scarify and aerate in autumn, reseed bare patches, and water deeply once a week in dry spells rather than a sprinkle daily."));
    s__LAWN_GREEN(py_str("Deeper green comes from feeding and watering rather than from seed or a spray: a spring lawn feed with nitrogen in it, and a deep soak once a week in dry weather instead of a daily sprinkle."));
