    s_HARVEST(py_dict(vec![(py_str("potato"), py_str("Lift new potatoes in June and July, once the flowers open, and maincrops in September and October when the tops have died back. Fork well beside the row so you do not spear them, then leave them on the soil for an hour to dry before storing in paper sacks in the dark.")), (py_str("carrot"), py_str("Pull carrots from June, thinning as you go, and lift the main crop in October before the first hard frost. They are ready when the shoulder is 2cm across. Twist the tops off before storing, because leaves keep drawing water, and keep them in damp sand in a cool shed.")), (py_str("onion"), py_str("Lift onions in July and August when the tops fall over and start to yellow: bend the tops down, leave them a fortnight on the soil in dry weather, then store in nets somewhere airy. An onion that is not properly dried is the one that rots and takes the rest of the sack with it.")), (py_str("lettuce"), py_str("Cut lettuce about eight to twelve weeks after sowing, in the morning when it is cold and crisp, at the base with a knife, and it will often come again. A lettuce that has started to shoot up a stem has bolted: pick it at once and eat it that day, because it turns bitter.")), (py_str("pea"), py_str("Pick peas from June, when the pods are full but still bright green and snap cleanly, and go along the row every two or three days. Leaving them on the plant stops it flowering, and a pod left too long goes starchy and tough.")), (py_str("bean"), g__bean_harvest()), (py_str("beetroot"), py_str("Beetroot is ready eight to ten weeks after sowing, at golf-ball size for eating fresh and up to tennis-ball size for storing. Twist the leaves off rather than cutting, so it does not bleed, and lift them before the first hard frost.")), (py_str("parsnip"), py_str("Lift parsnips from October through to February, and leave them in the ground until after a frost: the cold turns starch to sugar and they taste far better. Fork underneath the root rather than pulling, because a parsnip snaps at the shoulder and the best part stays in the soil.")), (py_str("leek"), py_str("Leeks can be lifted from September and stand in the ground all winter, which is the point of them: dig as you need them, and they will take hard frost. Earth up the stems a few weeks before lifting if you want more white.")), (py_str("cabbage"), g__brassica_harvest()), (py_str("courgette"), g__courgette_harvest()), (py_str("radish"), py_str("Radishes are ready about four weeks after sowing, at marble size: pull one to check rather than waiting for the row. Left longer they go woody and hot, so sow little and often instead of one big row.")), (py_str("swede"), py_str("Swedes are lifted from October, and are better after a frost, which sweetens them the way it does parsnips; they will stand in the ground into winter. Turnips are quick - six to eight weeks - and are best pulled small, at 5 to 7cm across."))]));
    s_HARVEST_MORE(py_tuple(vec![py_tuple(vec![py_tuple(vec![py_str("garlic")]), py_str("Lift garlic in July, when the bottom three leaves have yellowed and the rest are still green: stop watering a fortnight before, ease each bulb out with a fork, and dry them somewhere airy for two or three weeks before storing. Left in longer the bulbs split and they keep badly.")]), py_tuple(vec![py_tuple(vec![py_str("tomato"), py_str("tomatoes")]), py_str("Pick tomatoes from late July as they turn fully red, and take the whole truss in October before the first frost. Green ones left then will ripen on a windowsill next to a banana. A tomato is ready when it gives slightly in the hand and smells of tomato.")]), py_tuple(vec![py_tuple(vec![py_str("apple"), py_str("apples")]), py_str("Apples are ready from August for the earlies and October for the keepers: cup one and twist - ripe fruit comes away with the stalk on and the pips inside are brown. Pick in dry weather, use the windfalls first, and store only perfect fruit, in a cool dark place, not touching.")]), py_tuple(vec![py_tuple(vec![py_str("pear"), py_str("pears")]), py_str("Pick pears before they are ripe, from late August, while the flesh is still hard: lift one and twist, and when the stalk parts easily it is ready to finish indoors. A pear left to soften on the tree goes gritty and rotten at the core.")]), py_tuple(vec![py_tuple(vec![py_str("plum"), py_str("plums"), py_str("damson"), py_str("damsons")]), py_str("Plums are ready from August, when they colour up and give a little at the stalk end: pick with the stalk on and eat the soft ones first. A plum that comes away at a squeeze is over ripe, and the wasps find those the same day you do.")]), py_tuple(vec![py_tuple(vec![py_str("strawberry"), py_str("strawberries")]), py_str("Pick strawberries from June, when they are red all over including the tip, and pick with a short stalk in the cool of the morning. A berry that is pale at the tip will not sweeten after picking, and one left to rot takes the rest with it.")]), py_tuple(vec![py_tuple(vec![py_str("raspberry"), py_str("raspberries")]), py_str("Raspberries ripen from July: pick when the berry comes away from its core with no tug, and eat or freeze them the same day, because they keep a day at most. Autumn kinds crop on into October.")]), py_tuple(vec![py_tuple(vec![py_str("rhubarb")]), py_str("Pull rhubarb from April to the end of June, twisting each stalk out and leaving three on every crown, then stop: the plant needs the rest of the year to build up for next spring. Do not pull any in the first year after planting, and never eat the leaves.")]), py_tuple(vec![py_tuple(vec![py_str("sweetcorn"), py_str("sweet corn"), py_str("corn"), py_str("corn on the cob")]), py_str("Sweetcorn is ready in August and September: peel back a little husk and press a kernel with a fingernail - milky juice means ready, clear means wait, doughy means it has gone over. Cook it within the hour, because the sugar turns to starch fast.")]), py_tuple(vec![py_tuple(vec![py_str("chilli"), py_str("chillies"), py_str("chili"), py_str("chilies")]), py_str("Chillies are ready from late summer: pick green for a milder heat, or leave them on to turn red for the fullest flavour. Cut them with a short stalk and keep picking, because a plant left to ripen stops setting new fruit.")]), py_tuple(vec![py_tuple(vec![py_str("pumpkin"), py_str("pumpkins"), py_str("squash"), py_str("squashes")]), py_str("Pumpkins and squash are ready in September or October, when the skin has hardened so a fingernail will not mark it and the stalk has gone corky: cut with a long handle, cure them in the sun for a week, and they keep for months somewhere dry.")])]));
