    s_SOW_MONTH(py_dict(vec![(Py::Int(1), py_str("Not much goes in this month: plant garlic and shallots if the ground is not frozen, and start broad beans under cloches from late January. Chit early potatoes on a windowsill and order the seed you want for spring.")), (Py::Int(2), py_str("Broad beans and parsnips from late February, and onion sets and shallots as soon as the ground is workable. Sow tomatoes and chillies indoors under cover, and chit the early potatoes.")), (Py::Int(3), py_str("The month the plot opens: potatoes, carrots, onions, lettuce, peas, leeks, radish and cabbages all go in from now. Sow a short row every few weeks rather than one big sowing, so the crop comes over months instead of all at once.")), (Py::Int(4), py_str("Potatoes by mid-April, then beetroot and beans, courgettes indoors, and more lettuce and radish every three weeks. Keep fleece to hand: a late frost is the thing that sets April back.")), (Py::Int(5), py_str("Once the frost has gone: beans, courgettes, sweetcorn, squash and swede go out, and keep sowing lettuce and radish for a steady supply. Harden everything off for a week first.")), (Py::Int(6), py_str("Last chance for runner and french beans, courgettes and swede; keep salad and radish going. Water in the morning and mulch, because this is the month everything bolts.")), (Py::Int(7), py_str("Sow for the winter now: spring cabbage, kale, winter salad and more radish and lettuce for autumn. Lift onions and garlic as the tops fall over.")), (Py::Int(8), py_str("Spring cabbage, overwintering onion sets and winter salad go in, and the ground cleared of potatoes can take a green manure. Keep watering the beans and courgettes.")), (Py::Int(9), py_str("Sow winter salad and land cress, plant overwintering onion sets and garlic, and clear the spent crops into the compost. This is the month that decides next spring.")), (Py::Int(10), py_str("Plant garlic and overwintering broad beans for the earliest crop next year, and put in onion sets and shallots. Outdoors there is little else to sow except winter salad under cover, so clear and mulch the beds.")), (Py::Int(11), py_str("Plant garlic and broad beans if the ground is not frozen, mulch the empty beds, and order seed potatoes to chit after Christmas. Nothing else goes in outdoors.")), (Py::Int(12), py_str("Nothing goes in outdoors except garlic in a mild spell. Plan next year's rotation, order your seed, and start chitting early potatoes indoors after Christmas."))]));
