    s__WASP_STUNG(py_str("Scrape the sting out sideways with a fingernail or the edge of a card rather than pinching it, wash the spot and hold something cold on it for ten minutes; a wasp sting hurts for an hour or two and calms down with an antihistamine. A swollen face or throat, wheezing, or feeling faint needs 999, because that is anaphylaxis and it moves fast."));
